import pandas as pd


def main():
    movie_df = execute_sql_query('SELECT * FROM table_7094d14dcbfa3921163187bde7597aeb')
    characters_df = execute_sql_query('SELECT * FROM table_eb46adee8e29808d89c3d571adcd69df')
    actor_df = execute_sql_query('SELECT * FROM table_5b6fd6c53269f68ff9917438bca1d1cf')
    movie_actor_df = pd.merge(movie_df, characters_df, on='MovieID')
    movie_actor_actor_df = pd.merge(movie_actor_df, actor_df, on='ActorID')
    batman_movies = movie_actor_actor_df[movie_actor_actor_df['Title'] == 'Batman']
    if batman_movies.empty:
        result = {'type': 'string', 'value': "No movies with title 'Batman' found."}
    else:
        batman_actor_names = batman_movies['Name'].unique()
        result = {'type': 'string', 'value': ', '.join(map(str, batman_actor_names))}
    return result


result = main()
print(result)

