import pandas as pd
sql_query = """
SELECT T1.CharacterName, T2.Name
FROM table_eb46adee8e29808d89c3d571adcd69df AS T1
INNER JOIN table_5b6fd6c53269f68ff9917438bca1d1cf AS T2
ON T1.ActorID = T2.ActorID
WHERE LOWER(T2.Name) = LOWER('John Travolta')
"""
result_df = execute_sql_query(sql_query)
if not result_df.empty:
    characters = ', '.join(result_df['CharacterName'].tolist())
    result = {'type': 'string', 'value': f'Characters played by John Travolta: {characters}'}
else:
    result = {'type': 'string', 'value': 'No characters found for the specified actor.'}
