import pandas as pd
sql_query = """
SELECT T1.Title
FROM table_7094d14dcbfa3921163187bde7597aeb AS T1
INNER JOIN table_eb46adee8e29808d89c3d571adcd69df AS T2
ON T1.MovieID = T2.MovieID
WHERE T2.CharacterName = 'Dr. Archibald ''Moonlight'' Graham'
"""
result_df = execute_sql_query(sql_query)
if len(result_df) == 0:
    result = {'type': 'string', 'value': "No movie found with the character Dr. Archibald 'Moonlight' Graham."}
else:
    result = {'type': 'string', 'value': f"The character Dr. Archibald 'Moonlight' Graham is from the movie: {result_df['Title'].iloc[0]}."}

